#include <Arduino.h>
#include <string.h>

static const size_t CACHE = 16;
static const size_t ID_LEN = 40;
char recent[CACHE][ID_LEN] = {};
size_t head = 0;

bool seen(const char* id) {
  for (size_t i = 0; i < CACHE; ++i) {
    if (recent[i][0] && strncmp(recent[i], id, ID_LEN) == 0) return true;
  }
  return false;
}

void rememberId(const char* id) {
  strncpy(recent[head], id, ID_LEN - 1);
  recent[head][ID_LEN - 1] = '\0';
  head = (head + 1) % CACHE;
}

bool executeTask(const char* taskId, const char* command) {
  if (!taskId || !taskId[0] || seen(taskId)) return false;
  Serial.printf("EXEC %s: %s\n", taskId, command);
  // Real actuator/tool call goes here.
  rememberId(taskId);
  return true;
}

void setup() {
  Serial.begin(115200);
  executeTask("task-1", "light_on");   // executes
  executeTask("task-1", "light_on");   // ignored
  executeTask("task-2", "light_off");  // executes
}
