data class TaskUi(val id: String, val title: String, val status: String)

class TaskQueueViewModel : ViewModel() {
    private val _tasks = MutableStateFlow(
        listOf(
            TaskUi("1", "Open Chrome", "queued"),
            TaskUi("2", "Run server", "running")
        )
    )
    val tasks: StateFlow<List<TaskUi>> = _tasks.asStateFlow()

    fun updateStatus(id: String, status: String) {
        _tasks.update { list ->
            list.map { if (it.id == id) it.copy(status = status) else it }
        }
    }
}

@Composable
fun TaskQueueScreen(vm: TaskQueueViewModel = viewModel()) {
    val tasks by vm.tasks.collectAsStateWithLifecycle()
    LazyColumn {
        items(tasks, key = { it.id }) { task ->
            ListItem(
                headlineContent = { Text(task.title) },
                supportingContent = { Text(task.id) },
                trailingContent = { Text(task.status.uppercase()) }
            )
            HorizontalDivider()
        }
    }
}
